// Recipe photos and the home hero, generated by `npm run images`
// (scripts/images.mjs) as AVIF and WebP at several widths:
//   src/assets/photos/<id>-<width>.<avif|webp>
// Vite hashes each file; this module maps them to srcsets. Every photo is 4:3.

const files = import.meta.glob('../assets/photos/*.{avif,webp}', { eager: true, query: '?url', import: 'default' });

const index = {};
for (const [path, url] of Object.entries(files)) {
  const m = /\/([a-z0-9-]+)-(\d+)\.(avif|webp)$/.exec(path);
  if (!m) continue;
  const [, id, width, format] = m;
  index[id] ??= { avif: [], webp: [] };
  index[id][format].push([Number(width), url]);
}
for (const entry of Object.values(index)) {
  entry.avif.sort((a, b) => a[0] - b[0]);
  entry.webp.sort((a, b) => a[0] - b[0]);
}

const srcset = (list, max = Infinity) =>
  list
    .filter(([w]) => w <= max)
    .map(([w, url]) => `${url} ${w}w`)
    .join(', ');

/**
 * { avif, webp, src, width, height } for a photo id, or null if missing.
 * `max` caps the widths offered (thumbnails don't need the big files).
 */
export function imageFor(id, { max = Infinity, min = 0 } = {}) {
  const entry = index[id];
  if (!entry || !entry.webp.length) return null;
  const webp = entry.webp.filter(([w]) => w >= min);
  const avif = entry.avif.filter(([w]) => w >= min);
  const fallback = webp.filter(([w]) => w <= max).at(-1) ?? webp[0];
  const largest = entry.webp.at(-1)[0];
  return {
    avif: srcset(avif, max),
    webp: srcset(webp, max),
    src: fallback[1],
    width: largest,
    height: Math.round((largest * 3) / 4),
  };
}

/** The URL of one size (for meta tags and the offline precache). */
export function imageUrl(id, width, format = 'webp') {
  return index[id]?.[format].find(([w]) => w === width)?.[1] ?? null;
}

export const hasImage = (id) => Boolean(index[id]);

/** The home hero's `sizes` (the <img> and the preload in the head must agree). */
export const HERO_SIZES = '(min-width: 1184px) 440px, (min-width: 1024px) 37vw, (min-width: 768px) calc(100vw - 48px), calc(100vw - 32px)';

/** A recipe page's photo `sizes` (RecipeHero and the preload in the head). */
export const RECIPE_HERO_SIZES = '(min-width: 1184px) 1152px, (min-width: 768px) calc(100vw - 48px), calc(100vw - 32px)';
